   ```python
   def _ensure_script_dependencies(self, script_path: Path) -> tuple:
       """Scans script headers for `# requirements:` or `# pip:` directives and installs missing packages."""
       import importlib.util
       import subprocess

       try:
           code = script_path.read_text(encoding="utf-8", errors="replace")
       except Exception as exc:
           return False, f"Failed to read script for dependency inspection: {exc}"

       declared_pkgs = []
       for line in code.splitlines()[:50]:
           m = re.match(r"^\s*#\s*(?:requirements|pip)\s*:\s*(.+)$", line, flags=re.IGNORECASE)
           if m:
               raw_list = m.group(1)
               for item in re.split(r"[,\s]+", raw_list.strip()):
                   clean_pkg = item.strip()
                   if clean_pkg and clean_pkg not in declared_pkgs:
                       declared_pkgs.append(clean_pkg)

       if not declared_pkgs:
           return True, ""

       pkg_import_map = {
           "scikit-learn": "sklearn",
           "pillow": "PIL",
           "opencv-python": "cv2",
           "pyyaml": "yaml",
           "beautifulsoup4": "bs4",
       }

       missing_pkgs = []
       for pkg in declared_pkgs:
           base_pkg = re.split(r"[<>=!~]", pkg)[0].strip()
           if not base_pkg:
               continue
           mod_name = pkg_import_map.get(base_pkg.lower(), base_pkg.replace("-", "_"))
           try:
               if importlib.util.find_spec(mod_name) is None:
                   missing_pkgs.append(pkg)
           except Exception:
               missing_pkgs.append(pkg)

       if not missing_pkgs:
           return True, ""

       missing_str = ", ".join(missing_pkgs)
       self._set_status(f"📦 Installing missing dependencies: {html.escape(missing_str)}...", "#f59e0b")
       try:
           res = subprocess.run(
               [sys.executable, "-m", "pip", "install", "-q"] + missing_pkgs,
               capture_output=True,
               text=True,
               check=True,
           )
           install_msg = f"📦 JIT Dependency Installer: Successfully installed {missing_str}.\n"
           if res.stdout and res.stdout.strip():
               install_msg += f"{res.stdout.strip()}\n"
           self.console_log_html.value = self._format_console_terminal(install_msg, status_color="#10b981")
           return True, install_msg
       except subprocess.CalledProcessError as exc:
           err_detail = (exc.stderr or exc.stdout or str(exc)).strip()
           err_msg = f"✕ Failed to install dependencies ({missing_str}):\n{err_detail}"
           self.console_log_html.value = self._format_console_terminal(err_msg, status_color="#ef4444")
           return False, err_msg
       except Exception as exc:
           err_msg = f"✕ Unexpected error installing dependencies ({missing_str}): {exc}"
           self.console_log_html.value = self._format_console_terminal(err_msg, status_color="#ef4444")
           return False, err_msg
   ```

3. **Adaptive & Directive-Driven Timeout (`_resolve_adaptive_timeout`):**
   ```python
   def _resolve_adaptive_timeout(self, code: str) -> int:
       """Resolves execution watchdog timeout using explicit directive, AI workload heuristics, or default."""
       for line in code.splitlines()[:50]:
           m = re.match(r"^\s*#\s*timeout\s*:\s*(\d+)", line, flags=re.IGNORECASE)
           if m:
               try:
                   val = int(m.group(1))
                   if val > 0:
                       return val
               except ValueError:
                   pass

       heavy_patterns = [
           r"\btorch\b",
           r"\btriton\b",
           r"\btensorflow\b",
           r"\bjax\b",
           r"nn\.Module",
           r"epochs\s*=",
           r"train_losses",
           r"for\s+ep\s+in\s+range",
           r"hru_benchmark",
       ]
       for pat in heavy_patterns:
           if re.search(pat, code):
               return 600

       try:
           return int(getattr(self, "exec_timeout_seconds", 120))
       except Exception:
           return 120
   ```

4. **Refactored `execute_file` & Swarm Prompt Directives:**
   - `execute_file` now runs `_ensure_script_dependencies` and `_resolve_adaptive_timeout` before spawning the sandboxed `subprocess.Popen(..., start_new_session=True)` process, while preserving `self._active_proc` tracking and `finally: self._active_proc = None` cleanup.
   - Both the **Lead Architect** and **Specialist Coder** prompts in `_run_swarm_worker` now instruct agents to declare `# requirements: <pkgs>` and `# timeout: <seconds>` at the top of generated standalone scripts.

